mapper.select:
select d.id, d.name, c.name as categoryName, d.price, d.image, d.description, d.status, d.update_time as updateTime from dish d left join category c on d.category_id = c.id
and d.category_id = #{categoryId}
and d.name like concat('%', #{name}, '%')
and d.status = #{status}
order by d.update_time desc
